// Game layer for clans, derived only from real clan record fields:
// trophies are computed from faction points, wins and events held —
// nothing is stored or invented separately. There is NO crew level
// in ViceSunshine (removed site-wide, Nov 21 2026): crews are ranked
// by season points and trophies only. (A member's own personal
// ViceSunshine level is a different thing and is untouched.)
function clanGame(r: { factionPoints: number; wins: number; eventsHeld: number }, memberCount: number) {
  void memberCount;
  const trophies = r.factionPoints + r.wins * 100 + r.eventsHeld * 25;
  const league =
    trophies >= 2000 ? "Vice Legend" :
    trophies >= 1000 ? "Leonida Elite" :
    trophies >= 600 ? "Downtown Vice" :
    trophies >= 300 ? "Neon Strip" :
    trophies >= 100 ? "Vice Beach" : "Ocean Drive";
  return { trophies, league };
}
type ClanRankStats = {
  rankPoints: number;
  seasonPoints: number;
  effectiveSeasonPoints: number;
  effectiveLifetimePoints: number;
  multiplier: number;
  avgMemberLevel: number;
};
const EMPTY_RANK: ClanRankStats = {
  rankPoints: 0, seasonPoints: 0, effectiveSeasonPoints: 0,
  effectiveLifetimePoints: 0, multiplier: 1, avgMemberLevel: 1,
};
// The served URL of a crew's stored card-header picture
// (migration 0072). The header-picture upload was REMOVED
// (owner's direction, Nov 22 2026): no client renders this URL
// anymore — every crew header is its calling card artwork, else
// its crew colour. The field stays in the response shape for
// older readers; the upload/remove actions are gone.
async function clanHeaderUrl(ctx: Ctx, r: { headerBlobKey?: string }): Promise<string> {
  if (!r.headerBlobKey) return "";
  try { return await ctx.blobs.getUrl(r.headerBlobKey); } catch { return ""; }
}

// One member count, the same everywhere (owner audit, Nov 23
// 2026: Bruh read 10 members in one place and 11 in another).
// getClan's roster dedupes membership rows by gamertag — rows
// sharing a gamertag are the same player (stale-key history) —
// so every other member count (crew cards, rankings, search,
// the event-hosting gate) counts DISTINCT players the same way,
// never raw rows. The reads can never disagree again.
function distinctCrewMemberCounts(
  rows: { clanId: number; gamertag: string; playerKey: string }[],
): Map<number, number> {
  const people = new Map<number, Set<string>>();
  for (const m of rows) {
    const who = m.gamertag.trim().toLowerCase() || m.playerKey;
    if (!people.has(m.clanId)) people.set(m.clanId, new Set());
    people.get(m.clanId)?.add(who);
  }
  const counts = new Map<number, number>();
  for (const [clanId, set] of people) counts.set(clanId, set.size);
  return counts;
}

function clanSummaryOf(
  r: typeof schema.clans.$inferSelect,
  memberCount: number,
  rank: ClanRankStats = EMPTY_RANK,
  extra: { warsWon?: number; seasonRank?: number; headerImageUrl?: string } = {},
) {
  const g = clanGame(r, memberCount);
  return {
    // Crew tags are always shown uppercase (owner's rule) — the tag
    // is stored uppercase at creation; older rows are normalised
    // here so every surface shows the same tag.
    id: r.id, name: r.name, tag: r.tag.toUpperCase(), color: r.color, colorFinish: r.colorFinish || "", motto: r.motto,
    description: r.description, rules: r.rules ?? "", requirements: r.requirements ?? "",
    // Equipped CREW customisation (migration 0071): the crew badge
    // shown next to the crew name, and the crew page's accent theme.
    badge: r.badge ?? "", themeAccent: r.themeAccent ?? "",
    platform: r.platform, region: r.region,
    language: r.language, playstyle: r.playstyle, privacy: r.privacy,
    // Crew membership is UNLIMITED for every crew (owner's rule):
    // maxMembers is kept in the response shape for older readers
    // and is always 0, meaning no cap — joining is never blocked
    // by a member count.
    maxMembers: 0, memberCount, eventsHeld: r.eventsHeld,
    wins: r.wins, faction: r.faction, factionPoints: r.factionPoints,
    // The crew's equipped emblem effect (Crew Settings → Crew
    // customisation → Emblem Effects), stored on the crew row and
    // animated by ClanEmblem on every surface. "" = no effect.
    emblem: r.emblem || "shield", emblemEffect: r.emblemEffect || "", ...g,
    walletCredits: r.walletCredits ?? 0,
    // Clan banner styles are gone — the clan calling card is the banner.
    bannerStyle: "",
    callingCard: r.callingCard ?? "",
    // Stored crew-card header picture URL (migration 0072),
    // resolved by the caller (listClans / getClan) from the stored
    // blob key. No longer rendered anywhere — the upload feature
    // was removed (Nov 22 2026); kept only for response shape.
    headerImageUrl: extra.headerImageUrl ?? "",
    nameColor: "",
    warsWon: extra.warsWon ?? 0,
    seasonRank: extra.seasonRank ?? 0,
    ...rank,
  };
}

// This season's global rank per clan (1-based, by effective season
// points) — used for the Tracker-style stat tiles on clan cards and
// clan homes. (Clan Wars were removed at the owner's direction —
// Community Events hosted by clan Leaders replaced them.)
function seasonRankMap(stats: Map<number, ClanRankStats>): Map<number, number> {
  const sorted = [...stats.entries()].sort(
    (a, b) => b[1].effectiveSeasonPoints - a[1].effectiveSeasonPoints || b[1].effectiveLifetimePoints - a[1].effectiveLifetimePoints,
  );
  const map = new Map<number, number>();
  sorted.forEach(([clanId], i) => map.set(clanId, i + 1));
  return map;
}

