// A Database entry only counts as HAVING a picture when the blob
// behind its recorded key actually exists. getUrl() builds a URL
// for any key, existing or not, so a key whose picture file is
// gone (a failed or interrupted generation that still recorded a
// key, a repaint that never landed) used to hand the client a URL
// that serves nothing — the card rendered as a blank dark box with
// no fallback, and because the key was non-empty no painter ever
// queued the entry again: the picture was gone for good. Every
// reader and painter goes through this check now, so a missing
// picture file reads as "no picture" and the entry re-enters the
// painting queue until its picture is really there.
async function dbEntryHasPicture(ctx: Ctx, entry: { imageBlobKey: string }): Promise<boolean> {
  if (!entry.imageBlobKey) return false;
  try {
    return (await ctx.blobs.head(entry.imageBlobKey)) !== null;
  } catch {
    return false;
  }
}

// ---- Database duplicate merging (owner, Nov 21 2026: "why are
// there repetiton?") ----
// The automatic sync names each entry the way its source named
// it, so the same GTA VI item can land twice: once under a short
// name and once under the full name ("Jason" / "Jason Duval",
// "Lucia" / "Lucia Caminos", "Freddie" / "Freddie Gibbs"), once
// with the manufacturer written into the name and once with it in
// the manufacturer field ("Bravado Banshee" / "Banshee"), or with
// a different apostrophe character ("'90 Annis…" / "’90 Annis…").
// mergeDuplicateDbEntries folds each such set into ONE entry:
// the team's catalog entry survives first, then the entry with a
// real picture, the stronger status and the fuller name; the
// survivor inherits anything the dropped copy had that it lacks,
// member ratings move over, and the duplicate row is deleted.
// The matching is deliberately narrow — genuinely different
// items that merely share a word (Buccaneer vs Buccaneer Custom,
// Dominator vs Dominator GT, Carbine vs Carbine Rifle Mk II)
// are never merged.
function foldDbName(name: string): string {
  return name
    .toLowerCase()
    .replace(/[‘’ʼ´`]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/\s+/g, " ")
    .trim();
}

const DB_PLACE_SUFFIX_WORDS = new Set([
  "gun", "store", "shop", "customs", "garage", "bar", "club", "market",
  "apartment", "apartments", "safehouse", "station", "tattoo", "parlour",
  "parlor", "department", "liquor", "wholesale", "weapons",
]);

function dbEntriesSameEntity(
  a: { kind: string; name: string; manufacturer: string },
  b: { kind: string; name: string; manufacturer: string },
): boolean {
  if (a.kind !== b.kind) return false;
  const fa = foldDbName(a.name);
  const fb = foldDbName(b.name);
  if (!fa || !fb) return false;
  if (fa === fb) return true;
  // The same vehicle or weapon with the manufacturer written
  // into one copy's name and kept in the manufacturer field on
  // the other ("Shitzu Squalo" / "Squalo").
  const ma = foldDbName(a.manufacturer);
  const mb = foldDbName(b.manufacturer);
  if (ma && fb === `${ma} ${fa}`) return true;
  if (mb && fa === `${mb} ${fb}`) return true;
  const at = fa.split(" ");
  const bt = fb.split(" ");
  if (at.length === bt.length) return false;
  const [shortT, longT] = at.length < bt.length ? [at, bt] : [bt, at];
  if (!shortT.every((t, i) => longT[i] === t)) return false;
  const extra = longT.slice(shortT.length);
  // A character named by first name in one source and by full
  // name in another is the same person.
  if (a.kind === "Character") return true;
  // A location whose longer name only adds what kind of place
  // it is ("Black Eagle" / "Black Eagle gun store").
  if (a.kind === "Location") return extra.every((t) => DB_PLACE_SUFFIX_WORDS.has(t));
  return false;
}

function dbStatusRank(s: string): number {
  return s === "Confirmed in trailer" ? 3 : s === "Reported" ? 2 : s === "Returning from GTA V" ? 1 : 0;
}

type DbEntryRow = typeof schema.dbEntries.$inferSelect;

async function mergeDuplicateDbEntries(ctx: Ctx): Promise<{ merged: number; removedNames: string[] }> {
  const db = ctx.db<typeof schema>();
  const rows = await db.select().from(schema.dbEntries);
  // Group rows that name the same entity (union-find over the
  // conservative matcher above).
  const parent = new Map<number, number>();
  const findRoot = (x: number): number => {
    let r = x;
    let next = parent.get(r);
    while (next !== undefined && next !== r) {
      r = next;
      next = parent.get(r);
    }
    return r;
  };
  for (const r of rows) parent.set(r.id, r.id);
  for (let i = 0; i < rows.length; i++) {
    const a = rows[i];
    if (!a) continue;
    for (let j = i + 1; j < rows.length; j++) {
      const b = rows[j];
      if (!b) continue;
      if (dbEntriesSameEntity(a, b)) {
        const ra = findRoot(a.id);
        const rb = findRoot(b.id);
        if (ra !== rb) parent.set(ra, rb);
      }
    }
  }
  const groups = new Map<number, DbEntryRow[]>();
  for (const r of rows) {
    const root = findRoot(r.id);
    const list = groups.get(root) ?? [];
    list.push(r);
    groups.set(root, list);
  }
  const dupGroups = [...groups.values()].filter((g) => g.length > 1);
  if (dupGroups.length === 0) return { merged: 0, removedNames: [] };
  const ratings = await db.select().from(schema.dbRatings);
  let merged = 0;
  const removedNames: string[] = [];
  for (const group of dupGroups) {
    // Keeper: the team's catalog entry first, then a real
    // picture, the featured flag, the stronger status, clean
    // typography and the fuller name; oldest row breaks ties.
    const scored: { row: DbEntryRow; score: number }[] = [];
    for (const row of group) {
      let score = 0;
      if (row.autoDiscovered === 0) score += 100;
      if (await dbEntryHasPicture(ctx, row)) score += 40;
      if (row.featured === 1) score += 10;
      score += dbStatusRank(row.status) * 5;
      if (!/[‘’“”]/.test(row.name)) score += 2;
      score += Math.min(foldDbName(row.name).length, 60) / 100;
      scored.push({ row, score });
    }
    scored.sort((x, y) => y.score - x.score || x.row.id - y.row.id);
    const keeper = scored[0]?.row;
    if (!keeper) continue;
    const drops = scored.slice(1).map((s) => s.row);
    // Merge: the survivor keeps its own facts and inherits
    // anything it lacks from the dropped copies.
    let name = keeper.name;
    let category = keeper.category;
    let description = keeper.description;
    let type = keeper.type;
    let manufacturer = keeper.manufacturer;
    let drivetrain = keeper.drivetrain;
    let sourceName = keeper.sourceName;
    let sourceUrl = keeper.sourceUrl;
    let status = keeper.status;
    let featured = keeper.featured;
    let imageBlobKey = keeper.imageBlobKey;
    for (const drop of drops) {
      // Adopt the fuller form when the survivor only carries
      // the short form of the same name ("Jason" -> the dropped
      // copy's "Jason Duval").
      const fk = foldDbName(name);
      const fd = foldDbName(drop.name);
      if (fd !== fk && fd.startsWith(`${fk} `)) name = drop.name;
      if (!category && drop.category) category = drop.category;
      if (!description && drop.description) description = drop.description;
      if (!type && drop.type) type = drop.type;
      if (!manufacturer && drop.manufacturer) manufacturer = drop.manufacturer;
      if (!drivetrain && drop.drivetrain) drivetrain = drop.drivetrain;
      if (!sourceUrl && drop.sourceUrl) {
        sourceUrl = drop.sourceUrl;
        sourceName = drop.sourceName;
      }
      if (featured !== 1 && drop.featured === 1) featured = 1;
      // A catalog survivor's status is the team's call; an
      // auto-discovered survivor takes the stronger status of
      // the pair (a status is never downgraded by a merge).
      if (keeper.autoDiscovered === 1 && dbStatusRank(drop.status) > dbStatusRank(status)) {
        status = drop.status;
        if (drop.sourceUrl) {
          sourceUrl = drop.sourceUrl;
          sourceName = drop.sourceName;
        }
      }
      if (!(await dbEntryHasPicture(ctx, { imageBlobKey })) && (await dbEntryHasPicture(ctx, drop))) {
        imageBlobKey = drop.imageBlobKey;
      }
    }
    if (
      name !== keeper.name || category !== keeper.category || description !== keeper.description ||
      type !== keeper.type || manufacturer !== keeper.manufacturer || drivetrain !== keeper.drivetrain ||
      sourceName !== keeper.sourceName || sourceUrl !== keeper.sourceUrl || status !== keeper.status ||
      featured !== keeper.featured || imageBlobKey !== keeper.imageBlobKey
    ) {
      await db
        .update(schema.dbEntries)
        .set({
          name, category, description, type, manufacturer, drivetrain,
          sourceName, sourceUrl, status, featured, imageBlobKey,
          updatedAt: new Date(),
        })
        .where(eq(schema.dbEntries.id, keeper.id));
    }
    // Member ratings move to the survivor; a member who rated
    // both copies keeps one rating (the survivor's own).
    const keeperRatingKeys = new Set(ratings.filter((r) => r.entryId === keeper.id).map((r) => r.playerKey));
    for (const drop of drops) {
      for (const rating of ratings.filter((r) => r.entryId === drop.id)) {
        if (keeperRatingKeys.has(rating.playerKey)) {
          await db.delete(schema.dbRatings).where(eq(schema.dbRatings.id, rating.id));
        } else {
          await db.update(schema.dbRatings).set({ entryId: keeper.id }).where(eq(schema.dbRatings.id, rating.id));
          keeperRatingKeys.add(rating.playerKey);
        }
      }
      await db.delete(schema.dbEntries).where(eq(schema.dbEntries.id, drop.id));
      await db.insert(schema.contentCorrections).values({
        targetType: "Database entry",
        targetLabel: drop.name.slice(0, 160),
        field: "duplicate",
        oldValue: drop.name.slice(0, 500),
        newValue: `Merged into "${name}" — same ${keeper.kind.toLowerCase()} stored twice under a variant name`.slice(0, 500),
        sourceName: "ViceSunshine Database upkeep",
        sourceUrl: "",
      });
      merged += 1;
      removedNames.push(drop.name);
    }
  }
  return { merged, removedNames };
}

async function generateDbArtFor(ctx: Ctx, entry: typeof schema.dbEntries.$inferSelect): Promise<boolean> {
  const spec = DB_ART_SPECS[entry.name]
    ?? (entry.kind === "Vehicle"
      ? `a ${entry.category.toLowerCase()} vehicle called the ${entry.name}, with its own distinct body shape and colour`
      : entry.kind === "Weapon"
        ? `a ${entry.category.toLowerCase()} weapon called the ${entry.name}, side profile view on a flat solid dark navy background`
        : entry.kind === "Location"
          ? `the storefront of a ${entry.category.toLowerCase()} location called ${entry.name} on a neon coastal street`
          : `a character portrait of ${entry.name}`);
  // Framing rules (v4, owner's TRN-study direction): the Database
  // pictures follow TRN's framing per kind — Vehicles in-world at
  // 16:9 with varied framing, Weapons as flat cut-outs, Characters
  // as standardised 3:4 portraits with the face in the upper
  // third, Locations as wide eye-level exteriors. Every subject is
  // drawn EXACTLY as it is established in GTA VI — same face, same
  // features, same details, nothing added, nothing redesigned,
  // nothing changed — but as an original illustration from a
  // fresh viewpoint official artwork does not use.
  const vehicleAngles = ["three-quarter front view", "side profile view", "rear three-quarter view", "a tight front three-quarter close crop", "a wide in-world view"];
  const vehicleSettings = ["a neon-lit Vice City street at night", "a coastal causeway at golden hour", "a rain-slick downtown street under neon signs at night", "a beachfront boulevard at dusk", "a neon-lit Leonida Keys marina road at night"];
  const vehicleAngle = vehicleAngles[entry.id % vehicleAngles.length] ?? vehicleAngles[0];
  const vehicleSetting = vehicleSettings[entry.id % vehicleSettings.length] ?? vehicleSettings[0];
  const weaponCompact = /pistol|handgun|revolver|melee/i.test(entry.category) || /pistol|revolver/i.test(entry.name);
  const framing =
    entry.kind === "Vehicle"
      ? `Composition: an in-world shot of this one vehicle only — ${vehicleAngle}, the whole vehicle fully in frame and the clear subject filling most of the frame, on ${vehicleSetting}. The vehicle exactly as it is in GTA VI — same body, same details, nothing redesigned, nothing added — from a fresh viewpoint official artwork does not use. No other vehicles, no people, no readable text or logos.`
      : entry.kind === "Character"
        ? "Composition: a waist-up portrait of this one person only, seen from a fresh three-quarter viewpoint official artwork does not use — face in the upper third of the frame, head fully in frame with clear headroom above it, face and upper body centred at a consistent character-portrait scale, plain dark studio backdrop with neon rim light. Not a street scene, not a cityscape, no skyline, no other people. FACIAL FIDELITY IS MANDATORY: the face must match the character's established GTA VI look exactly — same face, same features, same hair, recognisable as that exact character. Facial hair ONLY where the description above explicitly states it (stated stubble, a stated beard); where the description states none, the character is clean-shaven — do NOT add a beard, a moustache, extra hair, scars, tattoos, glasses or any feature the character does not have. Nothing added, nothing changed."
        : entry.kind === "Location"
          ? "Composition: a wide, tightly cropped, eye-level exterior shot of this one location only, from a slight street-corner angle official artwork does not use — the building fills the frame, centred or slightly left, foreground street / lot across the bottom of the frame, sky / roof across the top, dusk light with neon rim light. The location exactly as established — same building, same details, nothing added. No readable text on any sign (abstract glowing shapes only), no logos, no close-up people."
          : `Composition: the weapon alone as a clean cut-out floating on a completely flat solid very dark navy background — one flat colour, no gradient, no environment, no floor, no scenery — horizontal side profile, barrel pointing right, stock / grip to the left, centred vertically. The weapon exactly as it is in GTA VI — same shape, same details, nothing redesigned, nothing added. ${weaponCompact ? "Shown at a natural smaller scale in the middle of the frame with generous empty dark space around it — do NOT enlarge it to fill the frame." : "The weapon stretches across 85–100% of the frame width."}`;
  try {
    // Every repaint lands under a FRESH versioned blob key
    // (db-art/entry-<id>-v<n>, n from meta db_art_versions). The
    // previous build repainted over the SAME key, so the picture's
    // URL never changed and browsers / CDNs kept serving the old
    // cached image — a finished repaint looked exactly like nothing
    // had changed. A new key = a new URL = the new picture shows.
    let versions: Record<string, number> = {};
    try {
      versions = JSON.parse((await getMeta(ctx, "db_art_versions")) || "{}") as Record<string, number>;
    } catch {
      versions = {};
    }
    const nextVersion = (versions[String(entry.id)] ?? 0) + 1;
    const media = await ctx.tool.generate_media(
      `Paint ${spec}. ${framing} This is original fan artwork for a community database — an illustration inspired by the item, not a copy of any official artwork. ${entry.kind === "Weapon" ? DB_ART_STYLE_FLAT : DB_ART_STYLE}`,
      { key: `db-art/entry-${entry.id}-v${nextVersion}`, orientation: entry.kind === "Character" ? "portrait" : "landscape" },
    );
    const db = ctx.db<typeof schema>();
    await db
      .update(schema.dbEntries)
      .set({ imageBlobKey: media.blobKey, updatedAt: new Date() })
      .where(eq(schema.dbEntries.id, entry.id));
    versions[String(entry.id)] = nextVersion;
    await setMeta(ctx, "db_art_versions", JSON.stringify(versions));
    return true;
  } catch (e) {
    // Never swallow a generation failure silently again: the last
    // failure is kept in meta db_art_last_error so a stalled repaint
    // is diagnosable instead of looking like "nothing changed".
    try {
      await setMeta(ctx, "db_art_last_error", JSON.stringify({
        entryId: entry.id,
        name: entry.name,
        message: e instanceof Error ? e.message : String(e),
        at: new Date().toISOString(),
      }));
    } catch { /* the failure record itself must never throw */ }
    return false;
  }
}

